{extern int __CanOpen_SDORead(int, unsigned char, unsigned short, unsigned char);}
{extern int __CanOpen_SDOResult(int, unsigned char, int, unsigned int*, unsigned int*);}
CASE STATE OF
  0:
    IF EXECUTE AND NOT EXECUTE0 THEN
      STATE := 1;
      DONE := FALSE;
      ERROR := FALSE;
      ERRORID := 0;
      VALUE := 0;
      BUSY := TRUE;
    END_IF;
  1:
    {{
      if(__CanOpen_SDORead(__GET_VAR(data__->NETWORK),
                           __GET_VAR(data__->NODEID),
                           __GET_VAR(data__->INDEX),
                           __GET_VAR(data__->SUBINDEX)) == 0){
          __SET_VAR(data__->,STATE,, 2);
      }else{
          __SET_VAR(data__->,ERROR,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }
    }}
  2:
    {{
      unsigned int value = 0, abortcode = 0;
      int res = __CanOpen_SDOResult(__GET_VAR(data__->NETWORK),
                                    __GET_VAR(data__->NODEID),
                                    1, &value, &abortcode);
      if(res > 0){
          __SET_VAR(data__->,VALUE,, value);
          __SET_VAR(data__->,DONE,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }else if(res < 0){
          __SET_VAR(data__->,ERRORID,, abortcode);
          __SET_VAR(data__->,ERROR,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }
    }}
  3:
    BUSY := FALSE;
    IF NOT EXECUTE THEN
      STATE := 0;
      DONE := FALSE;
      ERROR := FALSE;
    END_IF;
ELSE
  STATE := 0;
END_CASE;

EXECUTE0 := EXECUTE;

{extern int __CanOpen_SDOWrite(int, unsigned char, unsigned short, unsigned char, unsigned char, unsigned int);}
{extern int __CanOpen_SDOResult(int, unsigned char, int, unsigned int*, unsigned int*);}
CASE STATE OF
  0:
    IF EXECUTE AND NOT EXECUTE0 THEN
      STATE := 1;
      DONE := FALSE;
      ERROR := FALSE;
      ERRORID := 0;
      BUSY := TRUE;
    END_IF;
  1:
    {{
      if(__CanOpen_SDOWrite(__GET_VAR(data__->NETWORK),
                            __GET_VAR(data__->NODEID),
                            __GET_VAR(data__->INDEX),
                            __GET_VAR(data__->SUBINDEX),
                            __GET_VAR(data__->SIZE),
                            __GET_VAR(data__->VALUE)) == 0){
          __SET_VAR(data__->,STATE,, 2);
      }else{
          __SET_VAR(data__->,ERROR,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }
    }}
  2:
    {{
      unsigned int value = 0, abortcode = 0;
      int res = __CanOpen_SDOResult(__GET_VAR(data__->NETWORK),
                                    __GET_VAR(data__->NODEID),
                                    0, &value, &abortcode);
      if(res > 0){
          __SET_VAR(data__->,DONE,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }else if(res < 0){
          __SET_VAR(data__->,ERRORID,, abortcode);
          __SET_VAR(data__->,ERROR,, 1);
          __SET_VAR(data__->,STATE,, 3);
      }
    }}
  3:
    BUSY := FALSE;
    IF NOT EXECUTE THEN
      STATE := 0;
      DONE := FALSE;
      ERROR := FALSE;
    END_IF;
ELSE
  STATE := 0;
END_CASE;

EXECUTE0 := EXECUTE;
